class ute_syslog(ScopeController):
    """
    Introduction
    ************


    UTE library to save/manage syslog messages from eNB/I-PHY.


    Package requirements
    ********************


    * Python 2.7.x
    * setuptools >=2.1
    * pip >= 1.5
    * ute_installer >= 0.25

    Installation
    ************


    This section describes how to install **ute_syslog** as single library. For robotlte below steps are not needed.


    Installation for UTE test line
    ------------------------------


    ::

        pip install -U ute_syslog


    Installation for NON UTE test line
    ----------------------------------


    ::

        pip install -U -i http://pypi.ute.inside.nsn.com:25102 pip
        pip install -U -i http://pypi.ute.inside.nsn.com:25102 setuptools
        pip install -U -i http://pypi.ute.inside.nsn.com:25102 ute_installer
        pip install -U -i http://pypi.ute.inside.nsn.com:25102 ute_syslog


    Installation from SVN
    ---------------------


    ::

        pip install svn+https://ca_ute_test:utetest@svne1.access.nsn.com/isource/svnroot/utelibs/ute_syslog/trunk/#egg=ute_syslog


    Multiple instances
    ******************


    This library supports multiple setups where each can be specified by **alias** argument for every keyword.
    This argument can be specified as follow:
    ::

        Start syslog    log_dir=/tmp    log_name=enb    ip=192.168.255.126    alias=enb
        Start syslog    log_dir=/tmp    log_name=iphy   ip=192.168.200.126    alias=iphy

    Two naming conventions for the syslog tar file:
        Executed without alias (default) : syslog.tar.gz
        Executed with alias              : syslog_<alias name>.tar.gz

    .. _regexp:


    Regular expressions
    *******************


    Python support for regular expressions is described here: `Regular expression operations <https://docs.python.org/2/library/re.html>`_.

    Robot Framework design requires to escape some special characters used in regular expressions.
    Section about that is described under link:
    `Robot Framework User Guide <http://robotframework.org/robotframework/latest/RobotFrameworkUserGuide.html#escaping>`_.

    It is recommended to escape single and double quotes (' and ") because they could be interpreted by Robot Framework or Python.


    Examples
    --------


    For all examples only one keyword will be used but syntax is valid for all with regexp parameter.

    ::

        # Count messages that contain string: INF<any or none characters>Cell e.g. INFCell, INF Some Data Cell, INF 123 Cell
        Count syslog messages        INF.*Cell

        # Count messages that contain string: INF 'Some data'
        Count syslog messages        INF \\\\'Some data\\\\'

        # Count messages that contain some number: INF2, INF3
        Count syslog messages        INF\\\\d

        # Count messages that contain INF and from 3 to 4 numbers (e.g. INF123, INF5678)
        Count syslog messages        INF\\\\d{3,4}

        # Count messages that contain some special Robot Framework characters
        Count syslog messages        INF \\\\$Something \\\\@Something \\\\= Something


    Keywords
    ********


    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        super(ute_syslog, self).__init__()
        self.store = Store()

    def start_syslog(self, log_dir, log_name, ip='', ports=(51000, 51001, 51003, 50011), host_ip='127.0.0.1', file_limit=0,
                     add_line_number=False, virtualenv_dir=None, **kwargs):
        r"""Start collecting syslog.

        :param string  log_dir:  Path to directory where syslog file should be stored.
        :param string  log_name: Name of file where collected data should be stored during collection.
        :param string  ip:       Custom IP address where service should listen e.g. 192.168.255.126.
                                 By default all addresses and all interfaces (0.0.0.0/0).
        :param ports:            Single or List of ports which will be used to collect syslog data.
        :param string  host_ip:  IP Address of remote/local machine.
        :param integer file_limit:    Size limit for the log file. Log file will be splitted into smaller parts if configured size is greater than 0.
                                      Size limit is specified in bytes.
        :param bool    add_line_number:     Adds line numbers to the generated log file. Defaults to False
        :param str:    virtualenv_dir: use particular virtualenv when connecting to the host. If using localhost,
                                       by default this will try to use the current one.

        |

        :Supported SSH parameters are available via kwargs:
            * **ssh_username**   (string)  - Username for SSH authentication. Default is 'ute'.
            * **ssh_password**   (string)  - Password for SSH authentication. Default is 'ute'.
            * **ssh_port**       (integer) - SSH service port on specified machine. Default is 22.

        :Other supported parameters available via kwargs:
            * **cli_prefix**     (string)  - CLI prefix which will allow wrapping cli_syslog.py with another command or pass enviroment variables.
                                             Default is none.

        It is possible to change kwargs parameters by using syntax like in example below:

        ::

                Some keyword     ssh_username=test_user    ssh_password=test_pass    ssh_port=22

        :Multiple setups through aliases via kwargs:
            * **alias**   (string)   - Unique identifier for a certain syslog instance. Default is none.

        """
        alias = kwargs.get('alias')
        host_ip = host_ip if host_ip else '127.0.0.1'
        ssh_params_dict = dict(zip(['host_ip', 'username', 'password'],
                                   [host_ip, kwargs.get('ssh_username', 'ute'), kwargs.get('ssh_password', 'ute')]))
        ports = self._convert_to_list_of_ports(ports)
        file_limit = to_int(file_limit)
        ssh_connection = self._create_connected_ssh_client(host_ip, *self._fetch_ssh_parameters(**kwargs))
        # Ensure local virtualenv is used when connecting to localhost
        #
        # XXX: In theory, this check should include sys.prefix !=
        # sys.base_prefix instead of checking os.environ['VIRTUAL_ENV'].
        #
        # In practice... we don't care. This edge case is sharp only if the
        # user manages to run interpretter from outside of an active
        # virtualenv.
        if virtualenv_dir is None and 'ENABLE-PROFILER' in self._get_CM_TAGS():
            virtualenv_dir = '/home/ute/test_repo'
        if (virtualenv_dir is None
                and self._host_is_local(host_ip)
                and 'VIRTUAL_ENV' in os.environ):
            virtualenv_dir = os.environ['VIRTUAL_ENV']

        ctrl = Controller(ssh_connection=ssh_connection,
                          ssh_params=ssh_params_dict,
                          log_dir=log_dir,
                          log_name=log_name,
                          ip=ip,
                          ports=ports,
                          file_limit=file_limit,
                          add_line_number=add_line_number,
                          cli_prefix=kwargs.get('cli_prefix', None),
                          virtualenv_dir=virtualenv_dir)
        operator = LogOperator(ssh_connection=ssh_connection, log_pattern=ctrl.log_pattern)
        ctrl.start()
        self.store.add({'ctrl': ctrl,
                        'operator': operator,
                        'file_limit': file_limit,
                        'savepoints': {}},
                       alias)

    @staticmethod
    def _get_CM_TAGS():
        """
        Return CM_TAGS list from env.

        :return: CM_TAGS
        :rtype: list
        """
        cm_tags = os.getenv('CM_TAGS')
        if cm_tags is None:
            return []
        return cm_tags

    @staticmethod
    def _host_is_local(hostname):
        return hostname.startswith("127.")

    def count_syslog_messages(self, regexp, **kwargs):
        """Returns number of found messages in log file

        :param string regexp: Pattern used to find the message in the syslog file, see :ref:`regexp`.

        :return: Number of found messages
        :rtype: integer

        :Multiple setups through aliases via kwargs:
            * **alias**   (string)   - Unique identifier for a certain syslog instance. Default is none.

        """
        alias = kwargs.get('alias')
        return self.store.get(alias)['operator'].count_messages(regexp=regexp)

    def message_should_exist_in_syslog_file(self, regexp, **kwargs):
        """Check if a message exists in a file created by the syslog service.

        :param string regexp: Python regexp needed to perform the search operation, see :ref:`regexp`.

        :return: Found message.

        :note: Character '\' has to be additionally escaped because it is interpreted by the Robot Framework, e.g \\s has to be \\s.

        :Multiple setups through aliases via kwargs:
            * **alias**   (string)   - Unique identifier for a certain syslog instance. Default is none.

        :Other supported parameters available via kwargs:
            * **savepoint**     (string)  - timestamp of the syslog snippet captured via Capture Savepoint keyword
        """
        alias = kwargs.get('alias')
        savepoint = kwargs.get('savepoint')

        if savepoint:
            log_file = self.store.get(alias)['savepoints'][savepoint]
            if os.path.exists('{}.tar.gz'.format(log_file)):
                cmd = 'tar -xzf {}.tar.gz -C /tmp/'.format(log_file)
                self.store.get(alias)['ctrl'].connection.execute(cmd)
                log_file = '/tmp/{}'.format(os.path.basename(log_file))
            operator = LogOperator(ssh_connection=self.store.get(alias)['ctrl'].connection, log_pattern=log_file)
            return operator.message_exists(regexp)

        else:
            return self.store.get(alias)['operator'].message_exists(regexp)

    def wait_for_message_in_syslog_file(self, regexp, timeout, **kwargs):
        """Wait for a message to appear in the syslog file.

        :param string regexp:  Python regexp needed to perform the search operation, see :ref:`regexp`.
        :param string timeout: Max. time to wait for the message in seconds.

        :return: Found message
        :rtype: string

        :note: Character '\' has to be additionally escaped because it is interpreted by the Robot Framework, e.g \\s has to be \\s.

        |

        :Given timeout must be in format '1d 2h 3m 4s 5ms' with following rules:
            *  Time parts having zero value can be ignored (e.g. '3m 4s' is ok)
            *  Format is case and space insensitive
            *  Instead of 'd' it is also possible to use 'day' or 'days'
            *  Instead of 'h' also 'hour' and 'hours' are ok
            *  Instead of 'm' also 'minute', 'minutes', 'min' and 'mins' are ok
            *  Instead of 's' also 'second', 'seconds', 'sec' and 'secs' are ok
            *  Instead of 'ms' also 'millisecond', 'milliseconds' and 'millis' are ok
            *  It is possible to give time only as a float and then it is considered to be seconds
               (e.g. '123', '123.0', '123s', '2min 3s' are all equivalent)

        :Multiple setups through aliases via kwargs:
            * **alias**   (string)   - Unique identifier for a certain syslog instance. Default is none.

        """
        alias = kwargs.get('alias')
        timeout = to_seconds(timeout)
        return self.store.get(alias)['operator'].wait_for_message(regexp, timeout=timeout)

    def stop_and_collect_syslog(self, host_ip='127.0.0.1', unzip='false', subdirectory=None, **kwargs):
        r"""*DEPRECATED!!* Please use new keyword 'Collect Syslog Results'
            Stop syslogging and download the created file to the test result directory.
            Result directory is defined by --outputdir pybot option in test run.

        :param string  host_ip:      IP Address of the remote/local machine.
        :param boolean unzip:        Flag indicating whether downloaded logs should be extracted.
        :param string  subdirectory: Name of the folder to create in addition to the normal test result structure.

        |

        :Supported SSH parameters are available via kwargs:
            * **ssh_username**   (string)  - Username for SSH authentication. Default is 'ute'.
            * **ssh_password**   (string)  - Password for SSH authentication. Default is 'ute'.
            * **ssh_port**       (integer) - SSH service port on specified machine. Default is 22.

        :Multiple setups through aliases via kwargs:
            * **alias**   (string)   - Unique identifier for a certain syslog instance. Default is none.

        It is possible to change kwargs parameters by using syntax like in example below:

        ::

                Some keyword     ssh_username=test_user    ssh_password=test_pass    ssh_port=22

        :note: Format of result directory structure is: TestSuite1/TestSuite2/TestCase/SubFolder.
        """
        alias = kwargs.get('alias')
        if not self.store.has_alias(alias):
            logging.warning("Provided alias ({}) doesn't exist".format(alias))
            return
        self._stop_syslog(alias=alias)
        self._collect_syslog(host_ip=host_ip, unzip=unzip, subdirectory=subdirectory, **kwargs)
        self._teardown_syslog(alias=alias)

    def stop_syslog(self, **kwargs):
        """Stop syslogging.

        :Multiple setups through aliases via kwargs:
            * **alias**   (string)   - Unique identifier for a certain syslog instance. Default is none.

        """
        alias = kwargs.get('alias')
        if not self.store.has_alias(alias):
            logging.warning("Provided alias ({}) doesn't exist".format(alias))
            return
        self._stop_syslog(alias=alias)
        self._teardown_syslog(alias=alias)

    def collect_syslog_results(self, destination=None, unzip='true', **kwargs):
        """Stop syslog and download the created file to the destination path using SSH params from Start Syslog KW.

        :param string  destination: Path of packed file (filename.tar.gz) or existing path to directory where downloaded packed file should be stored
                                    Defaults to {log_path}/{log_path}.tar.gz from Start Syslog KW with same alias depending on unzip flag value
        :param boolean unzip:        Flag indicating whether downloaded logs should be extracted. defaults to true

        |


        :Multiple setups through aliases via kwargs:
            * **alias**   (string)   - Unique identifier for a certain syslog instance. Default is none.
        """
        alias = kwargs.get('alias')
        unpack = to_bool(unzip, skip_none=True)
        if not self.store.has_alias(alias):
            return
        destination = self._prepare_destination_path(alias, destination, unpack)
        self._stop_syslog(alias=alias)
        try:
            self._collect_results(alias, destination, unpack)
        except UteCommonDownloaderException as e:
            logging.error("Collecting syslog failed.")
            logging.error(e)
        self._teardown_syslog(alias=alias)

    def teardown_all_aliases_for_syslog(self):
        """This keyword stops all syslog instances and then collects the logs generated by all aliases.
        """
        self._out_of_scope()

    def capture_savepoint(self, **kwargs):
        """This keyword captures the current timestamp.

        :return: Get current timestamp on currently processing syslog.
        :rtype: string

        |

        :Multiple setups through aliases via kwargs:
            * **alias**   (string)   - Unique identifier for a certain syslog instance. Default is none.
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        log_path = self.store.get(alias)['ctrl'].log_path
        log_path = log_path if self.store.get(alias)['file_limit'] == 0 else self._merge_logs(log_path, alias)
        cmd = 'tail -n1 {log_path}'.format(log_path=log_path)
        return self.store.get(alias)['ctrl'].connection.execute(cmd)[:22]

    def collect_from_savepoint(self, savepoint, destination_file, file_limit=0, compress=False, **kwargs):
        """Collect logs starting from savepoint until the current saved logs

        :param string   savepoint:          Timestamp that will indicate where to start
        :param string   destination_file:   File path where the logs will be stored
        :param integer  file_limit:         Value in bytes (minimum 1000) to limit the size when splitting log files
        :param boolean  compress:           Flag for setting if the collected logs should be compressed to tar.gz.
                                            Default is False.

        |

        :Multiple setups through aliases via kwargs:
            * **alias**   (string)   - Unique identifier for a certain syslog instance. Default is none.
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        self.store.get(alias)['savepoints'].update({savepoint: destination_file})
        log_path = self.store.get(alias)['ctrl'].log_path
        log_path = log_path if self.store.get(alias)['file_limit'] == 0 else self._merge_logs(log_path, alias)
        cmd = "sed -n -e '/{savepoint}/,$p' {log_path} > {destination_file}"\
              .format(savepoint=savepoint, log_path=log_path, destination_file=destination_file)
        self.store.get(alias)['ctrl'].connection.execute(cmd)
        file_limit = int(file_limit)
        file_limit = file_limit if file_limit >= 1000 else 0

        if file_limit:
            split_cmd = "split -d -C {file_limit} {destination_file} {destination_file}_"\
                        .format(file_limit=file_limit, destination_file=destination_file)
            self.store.get(alias)['ctrl'].connection.execute(split_cmd)
            self.store.get(alias)['ctrl'].connection.execute("rm {}".format(destination_file))

        if to_bool(compress):
            destination = '{}.tar.gz'.format(destination_file)
            self._collect_results(alias, destination, unpack=False, files=[destination_file])

    def _collect_results(self, alias, destination, unpack, **kwargs):
        ctrl = self.store.get(alias)['ctrl']
        connection = self._prepare_connection_object(ctrl)
        files = kwargs.get('files') or [ctrl.log_pattern]
        Downloader(connection).download(files=files,
                                        destination=destination,
                                        unpack=unpack)

    def _convert_to_list_of_ports(self, ports):
        if isinstance(ports, (int, six.string_types)):
            return [to_int(ports)]
        else:
            return to_int_list(ports, skip_none=True)

    @retry_until_no_exception_or_out_of_attempts(3)
    def _attempt_ssh_client_login(self, ssh_ip, ssh_username, ssh_password, ssh_port):
        return connect(ssh_ip, ssh_username, ssh_password, ssh_port)

    def _create_connected_ssh_client(self, ssh_ip, ssh_username, ssh_password, ssh_port):
        ssh_connection = self._attempt_ssh_client_login(ssh_ip, ssh_username, ssh_password, ssh_port)
        return ssh_connection

    def _stop_syslog(self, alias):
        """Stop the syslog service."""
        self.store.get(alias)['ctrl'].stop()

    def _collect_syslog(self, host_ip, unzip, subdirectory, **kwargs):
        alias = kwargs.get('alias')
        ctrl = self.store.get(alias)['ctrl']
        unzip = to_bool(unzip, skip_none=True)
        tar_name = "syslog.tar.gz" if alias is None else "syslog_{}.tar.gz".format(alias)
        self._collect_syslog_for_ctrl(ctrl, host_ip, tar_name, unzip, subdirectory, **kwargs)

    def _collect_syslog_for_ctrl(self, ctrl, host_ip, tar_name, unzip, subdirectory, **kwargs):
        ssh_connection = self._create_connected_ssh_client(host_ip, *self._fetch_ssh_parameters(**kwargs))
        try:
            FileCollector(ssh_connection, tar_name=tar_name).get_files(
                files_list=[ctrl.log_pattern],
                unzip=unzip,
                subdirectory=subdirectory)
        finally:
            ssh_connection.disconnect()

    def _fetch_ssh_parameters(self, **kwargs):
        ssh_username = kwargs.get('ssh_username', 'ute')
        ssh_password = kwargs.get('ssh_password', 'ute')
        ssh_port = to_int(kwargs.get('ssh_port', 22))
        return ssh_username, ssh_password, ssh_port,

    def _prepare_connection_object(self, ctrl):
        connection = Connection()
        connection.host = ctrl.ssh_params['host_ip']
        connection.username = ctrl.ssh_params['username']
        connection.password = ctrl.ssh_params['password']
        return connection

    def _fetch_destination_from_start_syslog(self, alias, unpack):
        ctrl = self.store.get(alias)['ctrl']
        return os.path.dirname(ctrl.log_pattern) if unpack else '{}.tar.gz'.format(ctrl.log_pattern)

    def _prepare_destination_path(self, alias, destination, unpack):
        self._validate_destination(destination, unpack)
        if not destination:
            return self._fetch_destination_from_start_syslog(alias, unpack)
        elif os.path.dirname(destination) == '':
            return os.path.join(os.getcwd(), destination)
        else:
            return destination

    def _validate_destination(self, destination, unpack):
        if destination and unpack and destination.endswith('.tar.gz'):
            raise InvalidDestination("unzip has to be False if destination is a tar.gz file")
        elif destination and not unpack and not destination.endswith('.tar.gz'):
            raise InvalidDestination('Tar extension is not .tar.gz')

    def _teardown_syslog(self, alias):
        """Clean up information set by start_syslog keyword and stop working syslog."""
        self._delete_syslog_tmp(alias)
        ctrl = self.store.get(alias)['ctrl']
        ctrl.stop()
        ctrl.connection.disconnect()
        self.store.remove(alias)

    def _out_of_scope(self):
        """This stops all instance of syslogs when a test suite has ended and collects all the logs generated by all aliases."""
        for alias_name in self.store.aliases:
            self.collect_syslog_results(alias=alias_name)

    def _merge_logs(self, log_path, alias):
        merge_file = '/tmp/syslog_tmp_{timestamp}'.format(timestamp=time.time())
        filename = os.path.splitext(os.path.basename(log_path))[0]
        cmd = 'ls -v1 {log_path}/{filename}* | xargs cat > {savepoint}'.format(
            log_path=os.path.dirname(log_path), filename=filename, savepoint=merge_file)
        self.store.get(alias)['ctrl'].connection.execute(cmd)
        return merge_file

    def _delete_syslog_tmp(self, alias):
        cmd = 'rm -f /tmp/syslog_tmp*'
        savepoint_files = self.store.get(alias)['savepoints'].values()
        if savepoint_files:
            files = ['/tmp/{}'.format(os.path.basename(file)) for file in savepoint_files]
            cmd = 'rm -f /tmp/syslog_tmp* {}'.format(' '.join(files))
        self.store.get(alias)['ctrl'].connection.execute(cmd)
